const box=document.querySelector('.lightbox');let opener;document.querySelectorAll('[data-enlarge]').forEach(b=>b.addEventListener('click',()=>{opener=b;document.querySelector('#zoom-image').src=b.dataset.enlarge;document.querySelector('#zoom-image').alt=b.dataset.title;document.querySelector('#zoom-title').textContent=b.dataset.title;box.showModal();}));document.querySelector('[data-close]')?.addEventListener('click',()=>box.close());box?.addEventListener('close',()=>opener?.focus());